from PIL import Image, ImageDraw, ImageEnhance
im=Image.open('radiograph.jpg').convert('L')
im=ImageEnhance.Contrast(im).enhance(1.5).convert('RGB')
def crop(x0,y0,x1,y1,name,s=5):
    c=im.crop((x0,y0,x1,y1)).resize(((x1-x0)*s,(y1-y0)*s), Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for x in range(x0-x0%25,x1,25):
        d.line([((x-x0)*s,0),((x-x0)*s,(y1-y0)*s)],fill=(255,0,0),width=1)
        if x%50==0: d.text(((x-x0)*s+2,2),str(x),fill=(255,0,0))
    for y in range(y0-y0%25,y1,25):
        d.line([(0,(y-y0)*s),((x1-x0)*s,(y-y0)*s)],fill=(0,150,255),width=1)
        if y%50==0: d.text((2,(y-y0)*s+2),str(y),fill=(0,150,255))
    c.save(name)
crop(1560,440,1760,640,'posttooth.png')
